class Solution {
  public int findMaximumXOR(int[] nums) {
    int[][] trie = new int[nums.length * 31 + 1][2];
    int nodes = 1, best = 0;
    for (int x : nums) {
      int node = 0;
      for (int b = 30; b >= 0; b--) {
        int bit = x >> b & 1;
        if (trie[node][bit] == 0) trie[node][bit] = nodes++;
        node = trie[node][bit];
      }
    }
    for (int x : nums) {
      int node = 0, xor = 0;
      for (int b = 30; b >= 0; b--) {
        int bit = x >> b & 1;
        if (trie[node][bit ^ 1] != 0) {
          xor |= 1 << b;
          node = trie[node][bit ^ 1];
        } else node = trie[node][bit];
      }
      best = Math.max(best, xor);
    }
    return best;
  }
}
